// The treasury's coins: every technology in the owner's projects, struck with its emblem. The emblems
// are the brands' own marks, as drawn by Simple Icons 13.21.0 (path data CC0 1.0, simpleicons.org; each
// mark remains its owner's trademark), on a 24-unit square. A coin without a mark carries only its name,
// as some ancient coins carried only a legend.

export type Metal = "gold" | "silver" | "bronze" | "electrum";
export type CoinCategory = "ai" | "frontend" | "backend" | "cloud";

/** The metal each part of the craft is struck in. */
export const METALS: Record<CoinCategory, Metal> = {
  ai: "gold",
  frontend: "silver",
  backend: "bronze",
  cloud: "electrum",
};

export interface Coin {
  id: string;
  name: string;
  /** What is struck around the rim. */
  legend: string;
  category: CoinCategory;
  /** The works (by their index in the projects) built with this technology. */
  works: number[];
  /** The platform's services in use, for the coins shown with their own row in the tray. */
  services?: string[];
  /** SVG path data on a 24-unit square, or null for a legend-only coin. */
  logo: string | null;
}

